CREATE SCHEMA IF NOT EXISTS industrendindia AUTHORIZATION CURRENT_USER; SET search_path TO industrendindia,pg_catalog;
CREATE TABLE IF NOT EXISTS shopping_carts(cart_id uuid PRIMARY KEY,customer_id uuid,anonymous_token_hash char(64),status varchar(20) NOT NULL DEFAULT 'ACTIVE' CHECK(status IN('ACTIVE','CONVERTED','ABANDONED')),expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),CHECK(customer_id IS NOT NULL OR anonymous_token_hash IS NOT NULL)); CREATE UNIQUE INDEX IF NOT EXISTS shopping_carts_customer_active_uq ON shopping_carts(customer_id) WHERE status='ACTIVE' AND customer_id IS NOT NULL; CREATE INDEX IF NOT EXISTS shopping_carts_expiry_idx ON shopping_carts(expires_at) WHERE status='ACTIVE';
CREATE TABLE IF NOT EXISTS cart_items(cart_id uuid NOT NULL REFERENCES shopping_carts(cart_id) ON DELETE CASCADE,product_id uuid NOT NULL,quantity integer NOT NULL CHECK(quantity>0),unit_price_snapshot_minor bigint NOT NULL CHECK(unit_price_snapshot_minor>=0),added_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(cart_id,product_id));
CREATE TABLE IF NOT EXISTS orders(order_id uuid PRIMARY KEY,order_number bigint GENERATED ALWAYS AS IDENTITY UNIQUE,customer_id uuid NOT NULL,status varchar(24) NOT NULL DEFAULT 'PENDING' CHECK(status IN('PENDING','CONFIRMED','PAID','FULFILLED','CANCELLED','REFUNDED')),currency char(3) NOT NULL DEFAULT 'INR',subtotal_minor bigint NOT NULL CHECK(subtotal_minor>=0),shipping_minor bigint NOT NULL DEFAULT 0 CHECK(shipping_minor>=0),total_minor bigint NOT NULL CHECK(total_minor>=0),delivery_address jsonb NOT NULL,idempotency_key varchar(100) NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp()); CREATE INDEX IF NOT EXISTS orders_customer_created_idx ON orders(customer_id,created_at DESC); CREATE INDEX IF NOT EXISTS orders_status_created_idx ON orders(status,created_at DESC);
CREATE TABLE IF NOT EXISTS order_items(order_item_id uuid PRIMARY KEY,order_id uuid NOT NULL REFERENCES orders(order_id) ON DELETE CASCADE,product_id uuid,store_id uuid NOT NULL,sku varchar(100) NOT NULL,product_name varchar(220) NOT NULL,unit_price_minor bigint NOT NULL CHECK(unit_price_minor>=0),quantity integer NOT NULL CHECK(quantity>0),line_total_minor bigint NOT NULL CHECK(line_total_minor>=0)); CREATE INDEX IF NOT EXISTS order_items_order_idx ON order_items(order_id); CREATE INDEX IF NOT EXISTS order_items_store_idx ON order_items(store_id,order_id);
CREATE TABLE IF NOT EXISTS integration_outbox(event_id uuid PRIMARY KEY,aggregate_type varchar(80) NOT NULL,aggregate_id uuid NOT NULL,event_type varchar(120) NOT NULL,payload jsonb NOT NULL,status varchar(20) NOT NULL DEFAULT 'PENDING' CHECK(status IN('PENDING','PROCESSING','PUBLISHED','FAILED')),available_at timestamptz NOT NULL DEFAULT clock_timestamp(),attempt_count integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),published_at timestamptz); CREATE INDEX IF NOT EXISTS integration_outbox_dispatch_idx ON integration_outbox(status,available_at,created_at) WHERE status IN('PENDING','FAILED');
CREATE TABLE IF NOT EXISTS audit_events(audit_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,actor_type varchar(30) NOT NULL,actor_id uuid,action varchar(120) NOT NULL,entity_type varchar(80) NOT NULL,entity_id uuid,request_id varchar(100),ip_address inet,details jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT clock_timestamp()); CREATE INDEX IF NOT EXISTS audit_events_entity_idx ON audit_events(entity_type,entity_id,created_at DESC);
